package guidancecontent

import (
	"io/fs"

	"github.com/jaxxstorm/fed/internal/readiness"
)

// CMU preserves the class-specific MAY/SHOULD/MUST and availability conditions.
func CMU(rules, markdown fs.FS) (readiness.Package, error) {
	return communicationDraft(rules, markdown, "CMU", "cryptographic-module-use", 27, cmuRecipes, []communicationCapability{
		{"cmu-module-inventory", "Service cryptographic module provenance", "Cryptography owner and service owners", "Map federal-customer-data protection services to deployed cryptographic module versions, algorithms, operating environments and provider-managed dependencies. Identify CMVP validation records or update-stream lineage, validation status and agency-tenant default controls. Group services only where they actually use the same modules.", "The service-to-module map distinguishes validated modules, update streams, unvalidated modules and unknown provenance; new algorithms are not assumed covered by an older module validation."},
	}, []string{"Federal Customer Data", "Validation"})
}

var cmuRecipes = map[string]communicationRecipe{
	"CMU-CSO-CMD": {cap: "cmu-module-inventory", owner: "Cryptography owner", purpose: "Document the actual modules protecting federal customer data, rather than merely listing protocols or claiming encryption is enabled.", setup: "Reconcile data protection flows with service owners and inherited cryptographic services; establish the module/version evidence needed to group services using the same modules.", operate: "Document modules for each relevant service or justified service group and identify whether each is CMVP validated or an update stream of a validated module. Preserve unknown or unvalidated status rather than inferring validation from a product name.", records: "Service/group-to-module inventory, deployed versions and algorithm/environment details, vendor provenance for inherited services, CMVP validation references and update-stream lineage, with explicit validation status per entry.", review: "Trace each federal-data cryptographic service to its documented module. Check that service groups share the same modules and that validation or update-stream claims have supporting records; documentation alone does not establish the selected class's use obligation.", scope: "Every service or justified group using cryptographic services to protect federal customer data, including provider-managed and inherited services.", timing: "Identify deployment and documentation versions and the date validation status was observed; no numeric refresh interval is supplied by CMD.", insufficient: "An algorithm list, TLS version, encryption-enabled flag or vendor-wide FIPS marketing claim without service-to-module provenance.", trigger: "event"},
	"CMU-CSO-UVM": {cap: "cmu-module-inventory", owner: "Cryptography owner and platform owner", purpose: "Evaluate deployed cryptographic modules against the selected class's exact force and the scope of active CMVP validations, including permitted update streams.", setup: "Identify the selected class and federal-data protection paths. Map module versions and algorithms to active CMVP validations or a supported update stream; identify newly added algorithms separately.", operate: "Apply the selected class's MAY, SHOULD or MUST to module use. For adopted or required validated-module use, configure the actual data-protection paths to use supported modules or update streams with active validations. Never treat new, previously unvalidated algorithms in an update stream as covered. For SHOULD, document the weighed security-documentation decision; MAY does not require electing validated-module use.", records: "Selected class and use decision, module/algorithm inventory, actual runtime or configuration evidence, CMVP active-validation status as observed, update-stream lineage and algorithm comparison showing no reliance on newly added unvalidated algorithms for the claimed validation.", review: "Compare the deployed module, operating environment and algorithms with validation scope and update lineage. Separate active validation from certificate existence and deployment from mere availability; retain Class B permission, Class C recommendation and Class D mandate distinctly.", scope: "Cryptographic services protecting federal customer data throughout the offering, with exact module versions and inherited-service boundaries.", timing: "Retain validation-status observation dates, deployment revision dates and use period. Active validation is assessed for the claimed use period; no new numeric certificate-check interval is invented.", insufficient: "A certificate for a different module/version, a historical validation without active status, or an update-stream claim covering newly added unvalidated algorithms.", trigger: "event"},
	"CMU-CSO-CAT": {cap: "cmu-module-inventory", owner: "Tenant provisioning owner", purpose: "Make validated-module cryptographic services the agency-tenant default when available, preserving the SHOULD and availability condition.", setup: "Identify agency-tenant provisioning paths and default cryptographic settings, and determine which validated modules or qualifying update streams are available for each service.", operate: "Configure agency-tenant defaults to the available qualifying cryptographic services or document the carefully weighed decision on the recommendation. Record genuine availability limitations separately from a customer-selected override.", records: "Agency-tenant scope, provisioning templates/default policy revisions, availability analysis, module validation/update-stream references and effective settings for newly provisioned agency tenants; documented recommendation decisions and overrides.", review: "Compare provisioning defaults with actual effective tenant settings and the available qualifying modules. A later manual configuration does not establish a default, and a customer override does not describe the provider's default.", scope: "Agency tenants and their provisioning/default configuration paths, not unrelated commercial-only tenants.", timing: "Retain template/version dates, provisioning observations and availability/validation-status dates; no numeric recertification cycle is stated.", insufficient: "A single manually changed tenant, an opt-in feature listing or validation evidence without the agency default mapping.", trigger: "event"},
}
